import React, { useState, useRef, useEffect } from 'react';
import { ContextMenu } from 'primereact/contextmenu';
import { ProductService } from './service/ProductService';

export default function Template() {
    const [products, setProducts] = useState([]);
    const [selectedId, setSelectedId] = useState([]);
    const cm = useRef(null);

    // Item renderer template for items with badges or shortcuts
    const itemRenderer = (item, options) => (
        <div className="fxb fsb w-100p gp3 fvc" onClick={options.onClick}>
            {item.icon && <span className={`${item.icon} contextmenu-item-icon`} />}
            <span className="contextmenu-item-label">{item.label}</span>
            {item.badge && <span className="contextmenu-item-badge">{item.badge}</span>}
            {item.shortcut && <span className="contextmenu-item-shortcut">{item.shortcut}</span>}
        </div>
    );

    const items = [
        {
            label: 'Favorite',
            icon: 'pi pi-star',
            shortcut: '⌘+D',
            template: itemRenderer
        },
        {
            label: 'Add',
            icon: 'pi pi-shopping-cart',
            shortcut: '⌘+A',
            template: itemRenderer
        },
        {
            separator: true
        },
        {
            label: 'Share',
            icon: 'pi pi-share-alt',
            items: [
                {
                    label: 'Whatsapp',
                    icon: 'pi pi-whatsapp',
                    badge: 2,
                    template: itemRenderer
                },
                {
                    label: 'Instagram',
                    icon: 'pi pi-instagram',
                    badge: 3,
                    template: itemRenderer
                }
            ]
        }
    ];

    const onRightClick = (event, id) => {
      if (cm.current) {
          setSelectedId(id);
          cm.current.show(event);
      }
    };

    useEffect(() => {
        ProductService.getProductsSmall().then((data) => setProducts(data.slice(0, 5)));
    }, []); // eslint-disable-line react-hooks/exhaustive-deps

    return (
      <div className="fxb fvc gp2">
          <ul className="mg0 pd10 list-none bd rds2 fxb  column gp5 w-100p w300">
              {products.map((product) => (  
                  <li
                      key={product.id}
                      className={`pd10 bd rds2 transparent transition-all transition-duration-200 ${selectedId === product.id && 'bd-primary'}`}
                      onContextMenu={(e) => onRightClick(e, product.id)}
                  > 
                      <div className="fxb fvc gp2 fwb">
                          <img className="w48 h48 rds2" src={product.image} alt="product.name" />
                          <div className="fcol fvc gp1">
                              <span className="bold-font">{product.name}</span>
                              <span className="font-size12">{product.category}</span>
                          </div>
                          <span className="bold-font text-900">{product.price}</span>
                      </div>
                  </li>
              ))}
          </ul>
          <ContextMenu model={items} ref={cm} breakpoint="767px" onHide={() => setSelectedId(undefined)} />
      </div>
    )

}